25	static const int32_t IN_TENSOR_NUM = 5;
26	static const int32_t OUT_TENSOR_NUM = 2;
27	static const int32_t ROTARY_COEFF_TWO = 2;
28	static const int32_t ROTARY_COEFF_FOUR = 4;
29	static const int32_t PARAM_COS = 2;
30	static const int32_t PARAM_SIN = 3;
31	static const int32_t MAX_HEAD_SIZE = 4096;
32	static const int32_t MIN_HEAD_SIZE = 16;
