34	template <> Status CreateOperation(const infer::RopeParam &opParam, Operation **operation)
35	{
36	    if (operation == nullptr) {
37	        return ERROR_INVALID_PARAM;
38	    }
39	    OP_PARAM_RSV_CHECK(opParam);
40	    *operation = new (std::nothrow) RopeOperation(opParam);
41	    if (*operation == nullptr) {
42	        ATB_LOG(ERROR) << "failed to new operation";
43	        return ERROR_OUT_OF_HOST_MEMORY;
44	    }
45	    if (Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) {
46	        if (RopeAclnnRunner::LoadMethod() != NO_ERROR) {
47	            ATB_LOG(ERROR) << "Load aclnn function failed, please check your CANN version.";
48	            return ERROR_CANN_ERROR;
49	        }
50	        if (opParam.cosFormat != 0) {
51	            ATB_LOG(ERROR) << "Rope only supports cosFormat to be 0, but got " << opParam.cosFormat;
52	            return ERROR_INVALID_PARAM;
53	        }
54	    }
55	    return NO_ERROR;
56	}
