97	Status RopeOperation::SetupCheckImpl(const SVector<Tensor> &inTensors, const SVector<Tensor> &outTensors) const
98	{
99	    SVector<TensorDesc> inTensorDescs;
100	    for (size_t i = 0; i < inTensors.size(); i++) {
