113	Status RopeOperation::ParamCheck(const SVector<TensorDesc> &inTensorDescs) const
114	{
115	    if (param_.rotaryCoeff != ROTARY_COEFF_TWO && param_.rotaryCoeff != ROTARY_COEFF_FOUR &&
116	        param_.rotaryCoeff != inTensorDescs.at(PARAM_COS).shape.dims[1]) {
117	        ATB_LOG(ERROR) << GetLogPrefix() << "only supports rotaryCoeff to be one of 2,4,headdim, but got wrong rotaryCoeff: " << param_.rotaryCoeff;
118	        return ERROR_INVALID_PARAM;
119	    }
120	    if (inTensorDescs.at(PARAM_COS).shape.dims[1] % param_.rotaryCoeff != 0 || inTensorDescs.at(PARAM_SIN).shape.dims[1] % param_.rotaryCoeff != 0) {
121	        ATB_LOG(ERROR) << GetLogPrefix() << "rotaryCoeff:(" << param_.rotaryCoeff << ") is not divisible by COS dim[1](" <<
122	        inTensorDescs.at(PARAM_COS).shape.dims[1] << ") or SIN dim[1](" <<
123	        inTensorDescs.at(PARAM_SIN).shape.dims[1] << ")";
124	        return ERROR_INVALID_PARAM;
125	    }
126	    if (param_.cosFormat != 0 && param_.cosFormat != 1) {
127	        ATB_LOG(ERROR) << GetLogPrefix() << "only supports cosFormat as 0 or 1, but got wrong cosFormat: " << param_.cosFormat;
128	        return ERROR_INVALID_PARAM;
129	    }
130	
131	    return NO_ERROR;
132	}
