134	Status RopeOperation::DimCheck(const SVector<TensorDesc> &inTensorDescs) const
135	{
136	    if ((inTensorDescs.at(0).shape.dimNum != 2 && inTensorDescs.at(0).shape.dimNum != 4) || // dimNum: 2, 4
137	        (inTensorDescs.at(1).shape.dimNum != 2 && inTensorDescs.at(1).shape.dimNum != 4) || // dimNum: 2, 4
138	        inTensorDescs.at(2).shape.dimNum != 2 || inTensorDescs.at(3).shape.dimNum != 2 ||   // dimNum: 2, index: 3
139	        inTensorDescs.at(4).shape.dimNum != 1) {                                            // index: 4
140	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensor dimNum is not support, tensor[0-1] only support 2 or 4 dimNum,"
141	                       << "tensor[2-3] only support 2 dimNum, tensor[4] only support 1 dimNum"
142	                       << "inTensor[0-4] dimNum: " << inTensorDescs.at(0).shape.dimNum << ", "
143	                       << inTensorDescs.at(1).shape.dimNum << ", " << inTensorDescs.at(2).shape.dimNum // index: 2
144	                       << ", " << inTensorDescs.at(3).shape.dimNum                                     // index: 3
145	                       << ", " << inTensorDescs.at(4).shape.dimNum;                                    // index: 4
146	        return ERROR_INVALID_TENSOR_DIM;
147	    }
148	
149	    int64_t ntokens = inTensorDescs.at(0).shape.dimNum == 2 ?
150	                          inTensorDescs.at(0).shape.dims[0] :
151	                          (inTensorDescs.at(0).shape.dims[0] * inTensorDescs.at(0).shape.dims[1]);
152	    int64_t kDimNum = inTensorDescs.at(1).shape.dimNum;
153	    if ((kDimNum == 2 && inTensorDescs.at(1).shape.dims[0] != ntokens) || // dimNum: 2
154	        (kDimNum == 4 &&                                                  // dimNum: 4
155	         (inTensorDescs.at(1).shape.dims[0] * inTensorDescs.at(1).shape.dims[1]) != ntokens)) {
156	        ATB_LOG(ERROR) << GetLogPrefix() << "ntokens of q/k should be same. "
157	                       << "Q : " << TensorUtil::TensorDescToString(inTensorDescs.at(0))
158	                       << ", K: " << TensorUtil::TensorDescToString(inTensorDescs.at(1));
159	        return ERROR_INVALID_TENSOR_SIZE;
160	    }
161	
162	    if (Mki::PlatformInfo::Instance().GetPlatformType() != Mki::PlatformType::ASCEND_950) {
163	        if (inTensorDescs.at(2).shape.dims[1] > MAX_HEAD_SIZE || inTensorDescs.at(3).shape.dims[1] > MAX_HEAD_SIZE) {
164	            ATB_LOG(ERROR) << GetLogPrefix() << "head_size or head_size / 2 must be less than or equal to 4096!"
165	                        << "cos.dims[1]: " << inTensorDescs.at(2).shape.dims[1]
166	                        << "sin.dims[1]: " << inTensorDescs.at(3).shape.dims[1];
167	            return ERROR_INVALID_TENSOR_DIM;
168	        }
169	
170	        if (inTensorDescs.at(2).shape.dims[1] < MIN_HEAD_SIZE || inTensorDescs.at(3).shape.dims[1] < MIN_HEAD_SIZE) {
171	            ATB_LOG(ERROR) << GetLogPrefix() << "head_size or head_size / 2 must be greater than or equal to 16!"
172	                        << "cos.dims[1]: " << inTensorDescs.at(2).shape.dims[1]
173	                        << "sin.dims[1]: " << inTensorDescs.at(3).shape.dims[1];
174	            return ERROR_INVALID_TENSOR_DIM;
175	        }
176	    }
177	
178	    if (inTensorDescs.at(2).shape.dims[0] != inTensorDescs.at(3).shape.dims[0] || // index: 2, 3
179	        inTensorDescs.at(2).shape.dims[1] != inTensorDescs.at(3).shape.dims[1]    // index: 2, 3
180	    ) {
181	        ATB_LOG(ERROR) << GetLogPrefix() << "cos sin shape should be same. "
182	                       << "cos : " << TensorUtil::TensorDescToString(inTensorDescs.at(2))   // index: 2
183	                       << ", sin: " << TensorUtil::TensorDescToString(inTensorDescs.at(3)); // index: 3
184	        return ERROR_INVALID_TENSOR_SIZE;
185	    }
186	
187	    return HiddenSizeCheck(inTensorDescs);
188	}
189	
190	Status RopeOperation::HiddenSizeCheck(const SVector<TensorDesc> &inTensorDescs) const
191	{
192	    int64_t hiddenSizeQ = inTensorDescs.at(0).shape.dimNum == 4 ?
193	                              inTensorDescs.at(0).shape.dims[2] * inTensorDescs.at(0).shape.dims[3] :
194	                              inTensorDescs.at(0).shape.dims[1];
195	    int64_t hiddenSizeK = inTensorDescs.at(1).shape.dimNum == 4 ?
196	                              inTensorDescs.at(1).shape.dims[2] * inTensorDescs.at(1).shape.dims[3] :
197	                              inTensorDescs.at(1).shape.dims[1];
198	    if (hiddenSizeK == 0) {
199	        ATB_LOG(ERROR) << GetLogPrefix() << "hiddenSizeK should not be 0.";
200	        return ERROR_INVALID_TENSOR_SIZE;
201	    }
202	    if (hiddenSizeQ % hiddenSizeK != 0) {
203	        ATB_LOG(ERROR) << GetLogPrefix() << "hiddenSizeQ should be an integer multiple of hiddenSizeK, Q: "
204	                       << TensorUtil::TensorDescToString(inTensorDescs.at(0))
205	                       << ", K : " << TensorUtil::TensorDescToString(inTensorDescs.at(1))
206	                       << ", cos : " << TensorUtil::TensorDescToString(inTensorDescs.at(2)) // index: 2
207	                       << ", sin: " << TensorUtil::TensorDescToString(inTensorDescs.at(3)); // index: 3
208	        return ERROR_INVALID_TENSOR_SIZE;
209	    }
210	    int64_t headDim = inTensorDescs.at(PARAM_COS).shape.dims[1]; // 1: headDim
211	    if (hiddenSizeK % headDim != 0) {
212	        ATB_LOG(ERROR) << GetLogPrefix() << "hiddenSizeK should be an integer multiple of headDim, Q: "
213	                       << TensorUtil::TensorDescToString(inTensorDescs.at(0))
214	                       << ", cos : " << TensorUtil::TensorDescToString(inTensorDescs.at(2)); // index: 2
215	        return ERROR_INVALID_TENSOR_DIM;
216	    }
217	    return NO_ERROR;
218	}
