220	std::shared_ptr<Runner> RopeOperation::CreateRunner(Context &context) const
221	{
222	    if (Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) {
223	        return std::make_shared<RopeAclnnRunner>(param_);
224	    }
225	    ContextBase *contextBase = dynamic_cast<ContextBase *>(&context);
226	    if (!contextBase) {
227	        ATB_LOG(DEBUG) << "context cast to contextBase failed!";
228	        return nullptr;
229	    }
230	    int64_t runnerTypeIdx = RunnerTypeRegister::GetRunnerTypeIdx("RopeOpsRunner");
231	    RunnerPool &pool = contextBase->GetRunnerPool(runnerTypeIdx);
232	    Runner *runner = pool.MallocRunner<RopeOpsRunner, infer::RopeParam>(param_);
233	    if (!runner) {
234	        ATB_LOG(DEBUG) << "MallocRunner from pool failed!";
235	        return std::make_shared<RopeOpsRunner>(param_);
236	    }
237	    return std::shared_ptr<Runner>(runner, [&pool](Runner *runner) { pool.FreeRunner(runner); });
238	}
