138	{
139	    uint32_t idx = 0;
140	    TensorDesc xTensorDesc = inTensorDescs.at(idx++);
141	    TensorDesc gammaTensorDesc = inTensorDescs.at(idx++);
142	    TensorDesc keyRopeTensorDesc = inTensorDescs.at(idx++);
143	    TensorDesc cosTensorDesc = inTensorDescs.at(idx++);
144	    TensorDesc sinTensorDesc = inTensorDescs.at(idx++);
145	    idx++;
146	    TensorDesc keycacheInTensorDesc = inTensorDescs.at(idx++);
147	    if (!GammaBetaTensorCheck(xTensorDesc, gammaTensorDesc)) {
148	        ATB_LOG(ERROR) << GetLogPrefix() << "gammaTensorDesc error";
149	        return false;
150	    }
151	    if (xTensorDesc.shape.dims[DIM_ZERO] != keyRopeTensorDesc.shape.dims[DIM_ZERO]) {
152	        ATB_LOG(ERROR) << GetLogPrefix() << "The first dimension of the first input tensor "
