196	        ATB_LOG(ERROR) << GetLogPrefix() << "outTensor dimNum of the sixth intensor and the outtensor should be same";
197	        return ERROR_INVALID_TENSOR_SIZE;
198	    }
199	    for (uint64_t i = 0; i < tensorDesc1.shape.dimNum; i++) {
200	        if (tensorDesc1.shape.dims[i] != tensorDesc2.shape.dims[i]) {
201	            ATB_LOG(ERROR) << GetLogPrefix() << "outTensor dims of the sixth intensor and the outtensor should be same";
