20	static const uint32_t IN_TENSOR_SEQLENS = 2;
21	static const uint32_t OUT_TENSOR_NUM = 2;
22	static const uint32_t IN_TENSOR_NUM = 3;
23	static const uint32_t OUT_TENSOR_DIM_NUM = 2;
24	static const uint32_t ALIGNMENT = 32;
25	static const uint32_t MAX_BATCH_SIZE = 16;
26	static const uint32_t MAX_HEAD_DIM = 2048;
27	static const uint32_t MAX_NUM_TOKENS = 256000;
28	
29	namespace atb {
30	template <> Status CreateOperation(const infer::DynamicNTKParam &opParam, Operation **operation)
31	{
32	    if (operation == nullptr) {
33	        return ERROR_INVALID_PARAM;
34	    }
35	    OP_PARAM_RSV_CHECK(opParam);
36	    if (opParam.outDataType != ACL_FLOAT16 && opParam.outDataType != ACL_BF16) {
37	        ATB_LOG(ERROR) << "not support aclOutTensorType:" << opParam.outDataType;
38	        return ERROR_INVALID_PARAM;
39	    }
40	    if (opParam.outDataType == ACL_BF16 && !GetSingleton<Config>().Is910B()) {
41	        ATB_LOG(ERROR) << "only Atlas 800I A2 inference product supports bf16";
42	        return ERROR_INVALID_PARAM;
43	    }
44	    *operation = new (std::nothrow) DynamicNTKOperation(opParam);
45	    if (*operation == nullptr) {
46	        ATB_LOG(ERROR) << "failed to new operation";
47	        return ERROR_OUT_OF_HOST_MEMORY;
48	    }
49	    return NO_ERROR;
50	}
51	
52	DynamicNTKOperation::DynamicNTKOperation(const infer::DynamicNTKParam &param)
53	    : OperationBase("DynamicNTKOperation"), param_(param)
54	{
55	    operationIr_ = GetSingleton<AtbOperationIrCfg>().GetOperationIr("DynamicNTKOperation");
56	}
57	
58	DynamicNTKOperation::~DynamicNTKOperation() {}
59	
60	uint32_t DynamicNTKOperation::GetInputNum() const
61	{
62	    return IN_TENSOR_NUM;
63	}
64	
65	uint32_t DynamicNTKOperation::GetOutputNum() const
66	{
67	    return OUT_TENSOR_NUM;
68	}
69	
70	Status DynamicNTKOperation::InferShapeDimCheck(const SVector<TensorDesc> &inTensorDescs) const
71	{
72	    int64_t batch = inTensorDescs.at(IN_TENSOR_SEQLENS).shape.dims[0];
73	    if (batch != inTensorDescs.at(1).shape.dims[0] || batch > MAX_BATCH_SIZE) {
74	        ATB_LOG(ERROR) << GetLogPrefix() << "first dim of InvFreqIn and seqlens should be equal"
75	                       << "and should be no greater than 16";
76	        return ERROR_INVALID_TENSOR_DIM;
77	    }
78	    int64_t ntokens = inTensorDescs.at(0).shape.dims[0];
79	    if (ntokens > MAX_NUM_TOKENS) {
80	        ATB_LOG(ERROR) << GetLogPrefix() << "shape of positionIds should be no greater than 256000";
81	        return ERROR_INVALID_TENSOR_DIM;
82	    }
83	    int64_t headDim = inTensorDescs.at(1).shape.dims[1] * 2; // 输入InvFreqIn的大小是[head_dim / 2]
84	    if (headDim > MAX_HEAD_DIM) {
85	        ATB_LOG(ERROR) << GetLogPrefix()
86	                       << "head_dim should be no greater than 2048,"
87	                          "last dim of InvFreqIn tensor should be no greater than 1024.";
88	        return ERROR_INVALID_TENSOR_DIM;
89	    }
90	    if ((static_cast<uint64_t>(headDim) % static_cast<uint64_t>(ALIGNMENT) != 0)) {
91	        ATB_LOG(ERROR) << GetLogPrefix() << "head_dim is not support, should align 32";
92	        return ERROR_INVALID_TENSOR_DIM;
93	    }
94	    return NO_ERROR;
95	}
96	
97	Status DynamicNTKOperation::InferShapeCheckImpl(const SVector<TensorDesc> &inTensorDescs) const
98	{
99	    if (inTensorDescs.at(0).shape.dimNum != 1 || inTensorDescs.at(IN_TENSOR_SEQLENS).shape.dimNum != 1) {
100	        ATB_LOG(ERROR) << GetLogPrefix() << "dim numbers of positionIds and seqlens should be one";
101	        return ERROR_INVALID_TENSOR_DIM_NUM;
102	    }
103	    if (inTensorDescs.at(1).shape.dimNum != 2) { // 2:[batch, head_dim/2]
104	        ATB_LOG(ERROR) << GetLogPrefix() << "dim number of InvFreqIn should be two";
105	        return ERROR_INVALID_TENSOR_DIM_NUM;
106	    }
107	    Status st = NO_ERROR;
108	    st = InferShapeDimCheck(inTensorDescs);
109	    if (st != NO_ERROR) {
110	        return st;
111	    }
112	    return NO_ERROR;
113	}
114	
115	Status DynamicNTKOperation::InferShapeImpl(const SVector<TensorDesc> &inTensorDescs,
116	                                           SVector<TensorDesc> &outTensorDescs) const
117	{
118	    outTensorDescs.at(0).format = ACL_FORMAT_ND;
119	    outTensorDescs.at(0).dtype = param_.outDataType;
120	    outTensorDescs.at(0).shape.dimNum = OUT_TENSOR_DIM_NUM;
121	    outTensorDescs.at(0).shape.dims[0] = inTensorDescs.at(0).shape.dims[0];
122	    outTensorDescs.at(0).shape.dims[1] = inTensorDescs.at(1).shape.dims[1] * 2; // 输入InvFreqIn的大小是[head_dim / 2]
123	    outTensorDescs.at(1) = outTensorDescs.at(0);
124	    return NO_ERROR;
125	}
126	
127	Status DynamicNTKOperation::SetupCheckImpl(const SVector<Tensor> &inTensors, const SVector<Tensor> &outTensors) const
128	{
129	    SVector<TensorDesc> inTensorDescs = {};
130	    OperationUtil::InTensorsToInTensorDescs(inTensors, inTensorDescs);
131	    Status st = NO_ERROR;
132	    st = InferShapeCheckImpl(inTensorDescs);
133	    if (st != NO_ERROR) {
134	        return st;
135	    }
